"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.http.addresses import client_address, client_key, in_any

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit") or []
        self.trusted = config.section("clients") or ()
        self.now = None
        self.buckets = {}
        self.limited = {limit.name: 0 for limit in self.limits}


def setup(config):
    return State(config)


def _key_value(part, ctx, client):
    if part == "tenant":
        return ctx.tenant
    if part == "client":
        return client_key(client) if not isinstance(client, str) else client
    if part == "route":
        return ctx.route.name
    if part == "method":
        return ctx.request.method
    value = ctx.request.headers.get(part[7:])
    value = value.strip(" \t") if value is not None else None
    return value or None


def _entry(state, limit, key, now):
    """The key's state, refreshed to `now`: [level, refilled_at] or [used, window_start]."""
    slot = (limit.name, key)
    e = state.buckets.get(slot)
    if limit.algorithm == "token-bucket":
        if e is None:
            e = state.buckets[slot] = [Fraction(limit.capacity), now]
        else:
            e[0] = min(Fraction(limit.capacity), e[0] + Fraction((now - e[1]) * limit.rate, limit.per_ms))
            e[1] = now
    else:
        start = now - now % limit.per_ms
        if e is None or e[1] != start:
            e = state.buckets[slot] = [0, start]
    return e


def _values(limit, e, now, charge, cost):
    """(remaining, reset seconds, wait ms, refuses) with `charge` taken from the entry's state."""
    if limit.algorithm == "token-bucket":
        level = e[0] - charge
        per_rate = Fraction(limit.per_ms, limit.rate)
        remaining = math.floor(level)
        reset = math.ceil((limit.capacity - level) * per_rate / 1000)
        wait = (cost - level) * per_rate
        refuses = level < cost
    else:
        used = e[0] + charge
        remaining = limit.rate - used
        wait = Fraction(e[1] + limit.per_ms - now)
        reset = math.ceil(wait / 1000)
        refuses = used + cost > limit.rate
    return remaining, reset, wait, refuses


def handle(ctx, state):
    if not state.limits:
        return None
    request = ctx.request
    state.now = request.ts_ms if state.now is None else max(state.now, request.ts_ms)
    now = state.now
    client = client_address(request, state.trusted)
    covering = []
    for limit in state.limits:
        if limit.routes is not None and ctx.route.name not in limit.routes:
            continue
        if limit.methods is not None and request.method not in limit.methods:
            continue
        if not isinstance(client, str) and in_any(client, limit.exempt):
            continue
        parts = [_key_value(p, ctx, client) for p in limit.key]
        if any(p is None for p in parts):
            continue
        key = tuple(parts)
        covering.append((limit, _entry(state, limit, key, now), limit.cost.get(request.method, 1)))
    if not covering:
        return None

    results = []
    for limit, e, cost in covering:
        over = cost > limit.capacity
        remaining, reset, wait, refuses = _values(limit, e, now, 0, cost)
        results.append((limit, e, cost, over, refuses or over, (remaining, reset, wait)))
    refusing = [r for r in results if r[4]]

    if not refusing:
        best = None
        for limit, e, cost, _, _, _ in results:
            remaining, reset, _, _ = _values(limit, e, now, cost, cost)
            if best is None or remaining < best[0]:
                best = (remaining, reset, limit)
            if limit.algorithm == "token-bucket":
                e[0] -= cost
            else:
                e[0] += cost
        ctx.headers["RateLimit-Limit"] = str(best[2].capacity)
        ctx.headers["RateLimit-Remaining"] = str(best[0])
        ctx.headers["RateLimit-Reset"] = str(best[1])
        return None

    deciding = None
    for r in refusing:
        state.limited[r[0].name] += 1
        rank = (r[3], r[5][2])
        if deciding is None or rank > (deciding[3], deciding[5][2]):
            deciding = r
    limit, _, _, over, _, (remaining, reset, wait) = deciding
    ctx.headers["RateLimit-Limit"] = str(limit.capacity)
    ctx.headers["RateLimit-Remaining"] = str(remaining)
    ctx.headers["RateLimit-Reset"] = str(reset)
    if not over:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(wait / 1000)))
    return 429


def summary(state):
    if not state.limits:
        return {}
    return {"limited": dict(state.limited)}
