"""Client addresses and networks as the rate limiting stage reads them (docs/ratelimit.md, sections 3 and 7)."""

import ipaddress


def _normal(ip):
    """An IPv4 address mapped into IPv6 is the IPv4 address."""
    if ip.version == 6 and ip.ipv4_mapped is not None:
        return ip.ipv4_mapped
    return ip


def _port_ok(text: str) -> bool:
    return text.isascii() and text.isdigit() and len(text) <= 5 and int(text) <= 65535


def _v6(text: str):
    if "%" in text or ":" not in text:
        return None
    try:
        return ipaddress.IPv6Address(text)
    except ValueError:
        return None


def _v4(text: str):
    try:
        return ipaddress.IPv4Address(text)
    except ValueError:
        return None


def parse_address(text: str):
    """The address an entry stands for, or None when it is not an address."""
    if not text or text != text.strip() or any(c.isspace() for c in text):
        return None
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        rest = text[end + 1:]
        if rest and not (rest.startswith(":") and _port_ok(rest[1:])):
            return None
        ip = _v6(text[1:end])
    elif text.count(":") == 1:
        host, port = text.split(":")
        ip = _v4(host) if _port_ok(port) else None
    elif ":" in text:
        ip = _v6(text)
    else:
        ip = _v4(text)
    return None if ip is None else _normal(ip)


def parse_network(text: str):
    """A network in CIDR form (a bare address is that one address), or None."""
    addr, slash, bits = text.partition("/")
    if slash and not (bits.isascii() and bits.isdigit()):
        return None
    if "%" in text or any(c.isspace() for c in text):
        return None
    try:
        net = ipaddress.ip_network(text, strict=True)
    except ValueError:
        return None
    if net.version == 6 and net.prefixlen >= 96 and net.network_address.ipv4_mapped is not None:
        return ipaddress.IPv4Network((net.network_address.ipv4_mapped, net.prefixlen - 96))
    return net


def in_any(ip, networks) -> bool:
    return any(ip.version == n.version and ip in n for n in networks)


def client_key(ip) -> str:
    """The key form of a client address: IPv4 as is, IPv6 as its /64 network."""
    if ip.version == 4:
        return str(ip)
    return str(ipaddress.IPv6Network((ip, 64), strict=False))


def client_address(request, trusted):
    """The client address of a request (docs/ratelimit.md, section 7): an ip object, or the raw peer text."""
    peer = parse_address(request.peer)
    if peer is None or not in_any(peer, trusted):
        return peer if peer is not None else request.peer
    entries = [e.strip(" \t") for v in request.headers.get_all("X-Forwarded-For") for e in v.split(",")]
    if not entries:
        return peer
    previous = None
    for entry in reversed(entries):
        ip = parse_address(entry)
        if ip is None:
            return previous if previous is not None else peer
        if not in_any(ip, trusted):
            return ip
        previous = ip
    return parse_address(entries[0])
