"""[[limit]]: rate limits (docs/ratelimit.md, section 4)."""

import re
from dataclasses import dataclass

from frontdoor.config import values
from frontdoor.config.clients import networks, string_items
from frontdoor.errors import ConfigError

KEYS = ["name", "algorithm", "rate", "per", "burst", "key", "routes", "methods", "cost", "exempt"]
PARTS = ("tenant", "client", "route", "method")
_PER = re.compile(r"([0-9]+)(ms|s|m|h)", re.ASCII)
_MS = {"ms": 1, "s": 1000, "m": 60000, "h": 3600000}


@dataclass(frozen=True)
class Limit:
    name: str
    algorithm: str
    rate: int
    per_ms: int
    capacity: int
    key: tuple
    routes: frozenset | None
    methods: frozenset | None
    cost: dict
    exempt: tuple


def _per(t, what) -> int:
    text = values.string(t, "per", what)
    m = _PER.fullmatch(text)
    if not m or int(m.group(1)) == 0:
        raise ConfigError(f"{what}: per is not a duration such as \"1s\": {text!r}")
    return int(m.group(1)) * _MS[m.group(2)]


def _key(t, what) -> tuple:
    parts = values.string_list(t, "key", what)
    seen = set()
    for p in parts:
        if p.startswith("header:"):
            if not p[7:]:
                raise ConfigError(f"{what}: empty header name in key")
            norm = "header:" + p[7:].lower()
        elif p in PARTS:
            norm = p
        else:
            raise ConfigError(f"{what}: unknown key part {p!r}")
        if norm in seen:
            raise ConfigError(f"{what}: key part {p!r} appears twice")
        seen.add(norm)
    return tuple(parts)


def _cost(t, what) -> dict:
    raw = values.table(t.get("cost", {}), f"{what}: cost")
    out = {}
    for method, c in raw.items():
        if not isinstance(c, int) or isinstance(c, bool) or c < 1:
            raise ConfigError(f"{what}: cost of {method} must be a positive integer")
        if method.upper() in out:
            raise ConfigError(f"{what}: cost of {method.upper()} is given twice")
        out[method.upper()] = c
    return out


def parse(value) -> list:
    out = []
    names = set()
    for i, t in enumerate(values.tables(value, "limit"), 1):
        what = f"limit {i}"
        values.only_keys(t, KEYS, what)
        name = values.string(t, "name", what)
        what = f"limit {name}"
        if name in names:
            raise ConfigError(f"limit name {name!r} is used twice")
        names.add(name)
        algorithm = t.get("algorithm", "token-bucket")
        if algorithm not in ("token-bucket", "fixed-window"):
            raise ConfigError(f"{what}: unknown algorithm {algorithm!r}")
        rate = values.positive_int(t, "rate", what)
        per_ms = _per(t, what)
        if algorithm == "fixed-window":
            if "burst" in t:
                raise ConfigError(f"{what}: burst is only for the token bucket")
            capacity = rate
        else:
            capacity = values.positive_int(t, "burst", what, required=False, missing=rate)
        key = _key(t, what)
        routes = methods = None
        if "routes" in t:
            routes = frozenset(string_items(t, "routes", what))
        if "methods" in t:
            methods = frozenset(m.upper() for m in string_items(t, "methods", what))
        exempt = networks(string_items(t, "exempt", what), what) if "exempt" in t else ()
        out.append(Limit(name, algorithm, rate, per_ms, capacity, key, routes, methods, _cost(t, what), exempt))
    return out


def check_routes(config) -> None:
    known = {r.name for r in config.routes}
    for limit in config.section("limit", []):
        for r in sorted(limit.routes or ()):
            if r not in known:
                raise ConfigError(f"limit {limit.name}: {r!r} is not a route")
